from catalog import PRODUCTS, MODELS, CATEGORIES, ID_LINKS
from pathlib import Path
from html import escape
from urllib.parse import urlencode
import json
from xml.etree import ElementTree as ET

DIR=Path(__file__).resolve().parent
OUT=DIR.parents[1]/'golf-cart-parts'
WEB='https://a789b1.github.io/brand-directory/golf-cart-parts/'
paths=[]
def e(s): return escape(str(s),quote=True)
def money(n): return f'${n:,.2f}'
def icon(name, size=20):
    drawings={
      'search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
      'bag':'<path d="M5 8h14l1 13H4L5 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/>',
      'flag':'<path d="M5 21V3m0 1c4-4 8 3 15-1v10c-7 4-11-3-15 1"/>',
      'link':'<path d="M7 17 18 6M8 6h10v10"/>',
      'check':'<path d="m4 12 5 5L20 6"/>',
      'plus':'<path d="M12 5v14M5 12h14"/>',
      'minus':'<path d="M5 12h14"/>',
    }
    return f'<svg aria-hidden="true" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">{drawings[name]}</svg>'
def mark():
    return '<svg aria-hidden="true" width="35" height="34" viewBox="0 0 40 38" fill="currentColor"><path d="M3 32 13 6h4L7 32zm8 0L21 6h16l-2 5H23l-2 5h10l-2 5H19l-4 11z"/></svg>'
def brand(b): return f'<a class="wordmark" href="{b}" aria-label="Pinrail Cart Supply home">{mark()}<span>PINRAIL<small>CART SUPPLY</small></span></a>'
def asset(b,name):return b+'assets/'+name
def picture(b,p,small=False):
    s=p['slug']
    return f'<img alt="{e(p["alt"])}" width="887" height="887" src="{asset(b,s+("-small" if small else "")+".webp")}" srcset="{asset(b,s+"-small.webp")} 480w, {asset(b,s+".webp")} 887w" sizes="{"(max-width: 560px) 96vw, (max-width: 900px) 48vw, 420px" if small else "(max-width: 800px) 100vw, 52vw"}" {"loading=lazy" if small else "fetchpriority=high"}>'
def subtitle(p):
    return ' / '.join(dict.fromkeys(MODELS[k][0] for k,_,_ in p['fit']))
def card(b,p):
    return f'''<article class="part-card" data-card="{p['slug']}"><a href="{b}parts/{p['slug']}/" class="part-link"><div class="part-image">{picture(b,p,True)}</div><div class="card-sup"><span>{e(subtitle(p))}</span><span>{e(p['number'])}</span></div><div class="card-main"><h3>{e(p['name'])}</h3><strong>{money(p['price'])}</strong></div><p>{e(p['category'])}</p></a></article>'''
def finder(b):
    makes=list(dict.fromkeys(v[0] for v in MODELS.values()))
    return f'''<div class="finder" id="finder"><div class="finder-top"><h2>Parts finder</h2><div class="switch" aria-label="Search method"><button type="button" data-mode="vehicle" aria-pressed="true">By vehicle</button><button type="button" data-mode="number" aria-pressed="false">By part number</button></div></div><form class="fields" data-vehicle action="{b}catalog/"><label>Make<select name="make"><option value="">All makes</option>{''.join('<option>'+e(m)+'</option>' for m in makes)}</select></label><label>Model<select name="model"><option value="">All models</option></select></label><label>Model year<select name="year"><option value="">All years</option></select></label><button class="btn green" type="submit">{icon('search',18)} Find parts</button></form><form class="fields number-fields" data-number action="{b}catalog/" hidden><label>Part number or product name<input type="search" name="q" placeholder="e.g. ACC-BSKT04" autocomplete="off" required></label><button class="btn green" type="submit">{icon('search',18)} Search parts</button></form></div>'''
def breadcrumbs(b,links):
    return '<nav class="crumb" aria-label="Breadcrumb"><a href="'+b+'">Home</a>'+''.join(' <span aria-hidden="true">/</span> '+(f'<a href="{u}">{e(t)}</a>' if u else f'<span aria-current="page">{e(t)}</span>') for t,u in links)+'</nav>'
def external(u,text,cls='quiet'):
    return f'<a class="{cls}" href="{e(u)}" target="_blank" rel="noopener">{e(text)} {icon("link",15)}</a>'
def write(path,title,desc,body,*,active='',product=None,robots='index,follow'):
    b='../'*path.count('/') if path else './'
    canonical=WEB+path
    content=body(b) if callable(body) else body
    meta_img=WEB+'assets/'+(product['slug']+'.webp' if product else 'pine-course.webp')
    schema={'@context':'https://schema.org','@type':'WebSite','name':'Pinrail Cart Supply','url':WEB} if path=='' else None
    if product: schema={'@context':'https://schema.org','@type':'Product','name':product['name'],'description':product['summary'],'image':meta_img,'mpn':product['number'],'url':canonical,'category':product['category']}
    nav=lambda url,label,key: f'<a href="{b}{url}"'+(' aria-current="page"' if key==active else '')+'>'+label+'</a>'
    html=f'''<!doctype html><html lang="en-US" data-type="product"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} | Pinrail Cart Supply</title><meta name="description" content="{e(desc)}"><meta name="robots" content="{robots}"><meta name="theme-color" content="#173c30"><meta name="page-type" content="product"><meta name="site-kind" content="other"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{e(title)} | Pinrail Cart Supply"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:type" content="website"><meta property="og:image" content="{meta_img}"><link rel="icon" href="{b}assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="{b}assets/shop.css"><script defer src="{b}assets/data.js"></script><script defer src="{b}assets/shop.js"></script>{'<script type="application/ld+json">'+json.dumps(schema)+'</script>' if schema else ''}</head><body data-base="{b}" data-view="{active}" data-part="{product['slug'] if product else ''}"><a class="skip" href="#main">Skip to content</a><header><div class="wrap nav">{brand(b)}<nav aria-label="Main">{nav('catalog/','Parts catalog','catalog')}{nav('fitment-guide/','Fitment guide','guide')}</nav><a class="bag-link" href="{b}parts-list/" aria-label="Parts list">{icon('bag',19)}<span>Parts list</span><b data-count>0</b></a></div></header><main id="main">{content}</main><footer><div class="wrap foot"><div>{brand(b)}<p>Golf cart parts &amp; accessories.</p></div><div><b>Find a part</b><a href="{b}catalog/">Parts catalog</a><a href="{b}fitment-guide/">Vehicle fitment guide</a></div><div><b>Ordering</b><a href="{b}parts-list/">Your parts list</a><a href="{b}buying-guide/">Pricing, shipping &amp; returns</a></div></div><div class="wrap foot-end"><span>© 2026 Pinrail Cart Supply</span><span>United States · USD</span></div></footer></body></html>'''
    target=OUT/path/'index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html)
    if robots.startswith('index'):paths.append(canonical)

def home(b):
    return f'''<section class="hero"><picture><source media="(max-width: 650px)" srcset="{b}assets/pine-course-mobile.webp"><img src="{b}assets/pine-course.webp" width="1860" height="846" alt="Ivory golf cart on a pine-lined path in morning light" fetchpriority="high"></picture><div class="wrap hero-inner"><div class="hero-copy"><h1>Golf cart parts.<br><em>Find your fit.</em></h1><p>Shop accessories for Club Car, E-Z-GO and Yamaha. Start with your cart or a part number.</p><a class="btn lime" href="#finder">Find my parts</a></div></div></section><section class="wrap find-wrap" aria-label="Vehicle and part number search">{finder(b)}</section><section class="wrap featured"><div class="section-title"><div><span class="eyebrow">The parts catalog</span><h2>Featured accessories</h2></div><a class="under" href="{b}catalog/">Shop all parts</a></div><div class="grid">{''.join(card(b,PRODUCTS[i]) for i in [0,2,1])}</div></section><section class="wrap guide-band"><img src="{b}assets/seat-detail.webp" alt="Rear seat, roof support and storage rack on a golf cart" width="1270" height="847" loading="lazy"><div><span class="eyebrow">Fitment guide</span><h2>Which cart<br> do you own?</h2><p>Find the model and year on your vehicle record, then check the mounting points before you order.</p><a class="btn green" href="{b}fitment-guide/">Identify my cart</a></div></section>'''
def catalog(b):
    return f'''<div class="wrap">{breadcrumbs(b,[('Parts catalog',None)])}<div class="intro"><h1>Parts catalog</h1><p>Find accessories by vehicle, part number or the job at hand.</p></div>{finder(b)}<div class="catalog-refine" id="catalog-results"><div class="category-links" aria-label="Part categories">{''.join(f'<a data-cat="{e(c)}" href="?{urlencode({"category":c})}" class="chip">{e(c) if c else "All parts"}</a>' for c in ['',*CATEGORIES])}</div><label class="sort">Sort<select id="sort"><option value="featured">Featured</option><option value="asc">Price: low to high</option><option value="desc">Price: high to low</option></select></label></div><div class="match-line"><span id="results" role="status">{len(PRODUCTS)} parts</span><a href="./" id="reset" hidden>Clear filters</a></div><div class="grid collection">{''.join(card(b,p) for p in PRODUCTS)}</div><div class="empty" id="empty" hidden><h2>No catalog matches</h2><p>Try a different model year or search the complete part number. A midyear change may require a manual fitment check.</p><a class="btn green" href="./">Browse all parts</a></div></div>'''
def pdp(b,p):
    fitlines=''.join(f'<tr><th scope="row">{e(MODELS[k][0])} {e(MODELS[k][1])}</th><td>{a}–{z}</td></tr>' for k,a,z in p['fit'])
    return f'''<div class="wrap">{breadcrumbs(b,[('Parts catalog',b+'catalog/'),(p['name'],None)])}<section class="product"><div class="p-photo" style="background-image:url({b}assets/{p['slug']}-ground.webp)">{picture(b,p)}</div><div class="p-content"><span class="eyebrow">{e(p['category'])}</span><h1>{e(p['name'])}</h1><p class="part-id">Part No. <strong>{e(p['number'])}</strong></p><p class="price">{money(p['price'])} <small>USD</small></p><p class="lede">{e(p['summary'])}</p><div class="p-fit"><b>Vehicle fitment</b><div>{''.join(f'<span>{e(MODELS[k][0])} {e(MODELS[k][1])} · {a}–{z}</span>' for k,a,z in p['fit'])}</div><a href="#fitment">Check fit details</a></div><div class="buy-actions">{external(p['buy'],'Buy at '+p['retailer'],'btn green')}<button class="btn line" type="button" data-add="{e(p['slug'])}">{icon('plus',16)} Add to parts list</button></div><span class="feedback" role="status" data-feedback></span><p class="small">Retailer sets final price, availability and shipping.</p></div></section><div class="subnav"><a href="#fitment">Fitment</a><a href="#installation">Installation</a><a href="#specifications">Specifications</a></div><div class="detail-columns"><div><section id="fitment" class="detail-section"><span class="eyebrow">Compatibility</span><h2>Will it fit?</h2><div data-vehicle-match hidden></div><table><thead><tr><th scope="col">Model</th><th scope="col">Catalog years</th></tr></thead><tbody>{fitlines}</tbody></table><p>{e(p['condition'])}</p></section><section class="detail-section" id="installation"><span class="eyebrow">{e(p['mount'])}</span><h2>Installation notes</h2><ol class="steps">{''.join('<li>'+e(s)+'</li>' for s in p['steps'])}</ol></section></div><aside class="detail-section specs" id="specifications"><span class="eyebrow">Part details</span><h2>Specifications</h2><p>{e(p['detail'])}</p><dl>{''.join(f'<div><dt>{e(k)}</dt><dd>{e(v)}</dd></div>' for k,v in [('Part number',p['number']),('Installation area',p['mount']),*p['specs']])}</dl>{external(p['source'],'Fitment reference')}<p class="small">Illustrated product view. Use the supplier photos and instructions to confirm mounting details.</p></aside></div></div>'''
def guide(b):
    descriptions={'Club Car':'Use the model prefix on the serial number decal to identify your cart. Confirm the model year against the vehicle record, especially for a 2008 Precedent dash.','E-Z-GO':'Use the serial number and manufacturer code to identify the cart. TXT and RXV are separate families. For a TXT floor mat, also check the fuel type and horn location.','Yamaha':'Enter the primary ID (PID), or select the model and year in Yamaha’s parts finder. Drive and Drive2 use different model names. Check the rear seat and basket layout.'}
    return f'''<div class="wrap">{breadcrumbs(b,[('Fitment guide',None)])}<section class="guide-hero"><div><span class="eyebrow">Vehicle identification</span><h1>Find your cart’s<br><em>model and year.</em></h1><p>Start with the serial label or the paperwork for your vehicle. A similar body shape can hide a different mount, dash or floor layout.</p><a class="btn green" href="{b}catalog/">Open parts finder</a></div><img src="{b}assets/seat-detail.webp" width="1270" height="847" alt="Detail of the seat and rear rack mounting frame on a golf cart"></section><section class="guide-content"><h2>Identify your vehicle</h2>{''.join(f'<article class="guide-row"><h3>{e(m)}</h3><div><p>{e(descriptions[m])}</p>{external(url,m+" identification guide")}</div></article>' for m,url in ID_LINKS.items())}<h2>Check the part before you order</h2><ol class="steps"><li>Match the manufacturer part number if you have the original packaging. The catalog also accepts numbers without hyphens or spaces.</li><li>Confirm the model, year and configuration in the fitment table. Catalog year ranges cover the vehicles documented here.</li><li>Compare the original mount, cutouts and included hardware with the supplier listing. For a converted cart or midyear model, confirm fit directly with the supplier.</li></ol></section></div>'''
def buying(b):
    return f'''<div class="wrap">{breadcrumbs(b,[('Buying guide',None)])}<div class="intro"><h1>Ordering &amp; returns</h1><p>Choose a part here and complete your purchase with the listed U.S. retailer.</p></div><section class="readable"><h2>Prices and payment</h2><p>Prices are in U.S. dollars and are a reference for comparing parts. The retailer shows the current item price, tax and shipping at checkout and handles payment directly.</p><h2>Buying more than one part</h2><p>Add parts to your list to keep their part numbers and quantities together. Open each retailer link and choose the quantity on that retailer’s site. Parts from different sellers are ordered separately.</p><h2>Shipping and returns</h2><p>Enter your ZIP code on the retailer’s site for delivery options. Before opening or installing the part, check that seller’s return window, fitment rules and restocking fees. For an existing order, use the seller and order number on your receipt.</p><a class="btn green" href="{b}catalog/">Shop parts</a></section></div>'''
def parts_list(b):
    return f'''<div class="wrap list-page">{breadcrumbs(b,[('Parts list',None)])}<div class="intro"><h1>Your parts list</h1><p>Keep part numbers and quantities together, then order from each retailer.</p></div><div id="list-items"></div><div class="empty" id="list-empty"><h2>Your list is empty</h2><p>Save a part from its product page to compare and order it here.</p><a class="btn green" href="{b}catalog/">Browse parts</a></div><div id="list-total" hidden><div><span>Estimated parts total</span><strong id="total-value"></strong></div><p class="small">USD. Final pricing, shipping and tax are calculated by each retailer. Select your quantity again at checkout.</p></div><span class="sr" id="list-status" role="status"></span></div>'''
write('','Golf Cart Parts & Accessories','Find U.S. golf cart accessories by model, year or part number. Compare fitment, installation notes and retailer prices for Club Car, E-Z-GO and Yamaha.',home,active='home')
write('catalog/','Golf Cart Parts Catalog','Search the parts catalog by make, model, year or manufacturer part number. Filter Club Car, E-Z-GO and Yamaha golf cart accessories.',catalog,active='catalog')
for p in PRODUCTS:write('parts/'+p['slug']+'/',p['name']+' · '+p['number'],p['summary']+' Read fitment and installation details.',lambda b,p=p:pdp(b,p),active='product',product=p)
write('fitment-guide/','Golf Cart Model & Year Identification', 'Identify a Club Car, E-Z-GO or Yamaha golf cart and check mounts, model years and part numbers before ordering.',guide,active='guide')
write('buying-guide/','Ordering, Shipping & Returns','Find out how U.S. retailer pricing, shipping and returns work when ordering golf cart parts.',buying,active='buying')
write('parts-list/','Your Parts List','Review your saved golf cart parts and quantities and continue to the retailers.',parts_list,active='list',robots='noindex,follow')
dataset={'models':{k:{'make':v[0],'name':v[1],'start':v[2],'end':v[3]} for k,v in MODELS.items()},'parts':[{k:p[k] for k in ['slug','name','number','aliases','category','fit','price','buy','retailer']} for p in PRODUCTS]}
(OUT/'assets/data.js').write_text('window.Pinrail = '+json.dumps(dataset,ensure_ascii=False)+';\n')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+e(u)+'</loc></url>' for u in paths)+'</urlset>\n')
(OUT/'assets/mark.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40" fill="#173c30" rx="6"/><g fill="#d7ec8b"><path d="M4 31 13 8h4L8 31zm8 0L21 8h15l-2 5H23l-2 5h9l-2 5H19l-3 8z"/></g></svg>')
